// Decides who gets an email today and which kind:
//   appointment  = reminder the day before a booked appointment
//   reschedule   = appointment date passed, car never came in
//   due_1/2/3    = service due: heads-up, follow-up, final (overdue)
// Each item carries the email subject, Gemini brief, fallback body and the sheet values to write after sending.
const p = $('Set Service Parameters').first().json;
const today = DateTime.now().startOf('day');
const cap = Number(p.daily_send_cap) || 20;
const windowDays = Number(p.remind_days_before) || 7;
const followGap = Number(p.followup_after_days) || 4;
const grace = Number(p.missed_grace_days) || 1;
const maxResched = Number(p.max_reschedule_emails) || 2;
const defaultInterval = Number(p.default_interval_days) || 180;
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const norm = (v) => String(v ?? '').trim().toLowerCase();
const nice = (d) => d.toFormat('cccc d LLL yyyy');

function parseDate(v) {
  if (v === '' || v === null || v === undefined) return DateTime.invalid('empty');
  if (typeof v === 'number') return DateTime.fromISO('1899-12-30').plus({ days: v });
  const s = String(v).trim();
  for (const f of ['yyyy-MM-dd', 'M/d/yyyy', 'd/M/yyyy', 'yyyy/M/d', 'd-MMM-yyyy']) {
    const d = DateTime.fromFormat(s, f);
    if (d.isValid) return d.startOf('day');
  }
  return DateTime.fromISO(s).startOf('day');
}
const daysSince = (v) => {
  const d = DateTime.fromISO(String(v || ''));
  return d.isValid ? Math.floor(today.diff(d.startOf('day'), 'days').days) : 999;
};

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const email = String(r.email || '').trim();
  const status = norm(r.status);
  if (!emailRe.test(email) || norm(r.opt_out) === 'true' || status === 'opted_out') continue;

  const name = String(r.customer_name || '').trim().split(' ')[0] || 'there';
  const vehicle = String(r.vehicle || '').trim() || 'your vehicle';
  const serviceType = String(r.last_service_type || '').trim() || 'routine service';
  const last = parseDate(r.last_service_date);
  const appt = parseDate(r.appointment_date);
  const reschedCount = Number(r.reschedule_count) || 0;
  const current = {
    status: r.status || '', reminder_stage: r.reminder_stage ?? '', reminded_for_due_date: r.reminded_for_due_date || '',
    reschedule_count: reschedCount, appointment_reminded_for: r.appointment_reminded_for || ''
  };
  // card = the highlighted box in the email (label + date) and the button text (null = no button)
  const push = (type, priority, sortDays, subject, goal, facts, fallback, sheet, card) => out.push({ json: {
    row_number: r.row_number, email, customer_name: name, vehicle, type, priority, sort_days: sortDays,
    subject, email_goal: goal, facts, fallback_body: fallback,
    card_label: card.label, card_value: card.value, button_label: card.button,
    sheet: { ...current, ...sheet }
  }});

  // ---- A. Appointment flows ----
  if (appt.isValid && ['booked', 'booking_requested', 'reschedule_requested'].includes(status)) {
    const apptISO = appt.toISODate();
    const daysToAppt = Math.round(appt.diff(today, 'days').days);
    const visited = last.isValid && last >= appt;
    if (!visited) {
      if (status === 'booked' && daysToAppt === 1 && current.appointment_reminded_for !== apptISO) {
        push('appointment', 0, daysToAppt,
          `Service reminder: see you tomorrow, ${nice(appt)}`,
          'Remind them of their appointment tomorrow. Ask them to reply if they need to change it.',
          `Appointment: ${nice(appt)} for the ${vehicle} (${serviceType}). Shop phone: ${p.shop_phone}.`,
          `Just a quick reminder that your ${vehicle} is booked in with us tomorrow for its ${serviceType.toLowerCase()}.\n\nIf you need to change the time, simply reply to this email and we'll sort it out.`,
          { appointment_reminded_for: apptISO },
          { label: 'Appointment', value: nice(appt), button: null });
        continue;
      }
      if (daysToAppt <= -grace) {
        const first = status === 'booked' || status === 'booking_requested';
        const again = status === 'reschedule_requested' && reschedCount < maxResched && daysSince(r.last_reminder_at) >= followGap;
        if (first || again) {
          const n = first ? 1 : reschedCount + 1;
          push('reschedule', 1, daysToAppt,
            `Service reminder: let's find a new time for your ${vehicle}`,
            n === 1
              ? 'They missed their appointment. Say we missed them (no blame), the service is still needed, and invite them to pick a new time.'
              : 'Short, friendly second nudge to rebook a missed appointment. Keep it to 2-3 sentences.',
            `Missed appointment: ${nice(appt)} for the ${vehicle} (${serviceType}). Booking link: ${p.booking_link}. Shop phone: ${p.shop_phone}.`,
            `We had your ${vehicle} booked in on ${nice(appt)}, but we didn't get to see you. No problem, these things happen.\n\nThe service is still due, so pick a new time that suits you below, or just reply with a day.`,
            { status: 'reschedule_requested', reschedule_count: n },
            { label: 'Missed appointment', value: nice(appt), button: 'Pick a new time' });
        }
      }
      continue; // an appointment is pending or being rebooked: no regular due reminders
    }
  }

  // ---- B. Service due reminders ----
  if (!last.isValid) continue;
  const interval = Number(r.service_interval_days) || defaultInterval;
  const due = last.plus({ days: interval });
  const dueISO = due.toISODate();
  const daysUntilDue = Math.round(due.diff(today, 'days').days);
  const sameCycle = String(r.reminded_for_due_date || '').trim() === dueISO;
  const stage = sameCycle ? (Number(r.reminder_stage) || 1) : 0;
  if (sameCycle && ['booked', 'booking_requested', 'declined', 'needs_owner_reply', 'reschedule_requested'].includes(status)) continue;

  let next = 0;
  if (stage === 0 && daysUntilDue <= windowDays) next = 1;
  else if (stage === 1 && daysSince(r.last_reminder_at) >= followGap) next = 2;
  else if (stage === 2 && daysUntilDue < 0 && daysSince(r.last_reminder_at) >= followGap) next = 3;
  if (!next) continue;

  const when = daysUntilDue < 0 ? `was due on ${nice(due)}` : `is due on ${nice(due)}`;
  const subjects = {
    1: `Service reminder: your ${vehicle} is due ${nice(due)}`,
    2: `Service reminder follow-up: your ${vehicle}`,
    3: `Final service reminder: your ${vehicle} is overdue`
  };
  const goals = {
    1: 'Friendly heads-up that the next service is coming up. Invite them to book.',
    2: 'Brief, polite follow-up to an unanswered reminder. Acknowledge they may be busy. Shorter than a first reminder.',
    3: 'Final reminder: the service is overdue. Calmly say staying on schedule keeps the vehicle safe and reliable, and that this is the last reminder for this service. No scare tactics.'
  };
  push(`due_${next}`, 2, daysUntilDue, subjects[next], goals[next],
    `Vehicle: ${vehicle}. Last service: ${serviceType} on ${nice(last)}. Next service ${when} (${daysUntilDue} days from today). Booking link: ${p.booking_link}. Shop phone: ${p.shop_phone}.`,
    `Your ${vehicle} ${when}. Staying on schedule keeps it safe, reliable and running well.\n\nBook a time below, or just reply with a day that suits you.`,
    { status: 'reminded', reminder_stage: next, reminded_for_due_date: dueISO },
    { label: daysUntilDue < 0 ? 'Service was due' : 'Service due', value: nice(due), button: 'Book my service' });
}

// Appointment reminders first, then reschedules, then the most overdue services.
out.sort((a, b) => a.json.priority - b.json.priority || a.json.sort_days - b.json.sort_days);
return out.slice(0, cap);

// Wraps Gemini's text in a clean, mobile-friendly HTML email.
// If Gemini failed or returned too little, the fallback text from "Pick Today's Emails" is used.
const c = $('Loop Over Customers').item.json;
const p = $('Set Service Parameters').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Remove anything the template already adds, in case the model added it anyway.
let lines = String($input.item.json.text || '').trim().split(/\r?\n/);
if (/^(hi|hello|dear|hey)\b/i.test((lines[0] || '').trim())) lines.shift();
lines = lines.filter((l) => !/reply stop/i.test(l));
const signOff = lines.findIndex((l) => /^(the team at|best|thanks|thank you|regards|kind regards|warm regards|cheers|sincerely)\b/i.test(l.trim()));
if (signOff > 0) lines = lines.slice(0, signOff);
let text = lines.join('\n').trim();
if (text.length < 30) text = c.fallback_body;

const paragraphs = text.split(/\n\s*\n/).map((t) => t.replace(/\s*\n\s*/g, ' ').trim()).filter(Boolean)
  .map((t) => `<p style="margin:0 0 16px;">${esc(t)}</p>`).join('');

const button = c.button_label
  ? `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:4px 0 20px;"><tr><td style="background:#1a73e8;border-radius:6px;"><a href="${esc(p.booking_link)}" style="display:inline-block;padding:12px 26px;color:#ffffff;text-decoration:none;font-weight:bold;font-size:15px;">${esc(c.button_label)}</a></td></tr></table>`
  : '';

const card = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5fd;border-radius:6px;margin:0 0 20px;"><tr>
<td style="padding:14px 16px;font-size:13px;color:#5f6368;width:50%;">Vehicle<br><strong style="font-size:15px;color:#202124;">${esc(c.vehicle)}</strong></td>
<td style="padding:14px 16px;font-size:13px;color:#5f6368;width:50%;">${esc(c.card_label)}<br><strong style="font-size:15px;color:#202124;">${esc(c.card_value)}</strong></td>
</tr></table>`;

const html = `<div style="background:#f4f5f7;padding:24px 12px;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:8px;">
<tr><td style="background:#1a73e8;padding:18px 28px;border-radius:8px 8px 0 0;color:#ffffff;font-size:18px;font-weight:bold;">${esc(p.shop_name)}</td></tr>
<tr><td style="padding:28px 28px 8px;color:#202124;font-size:15px;line-height:1.6;">
<p style="margin:0 0 16px;">Hi ${esc(c.customer_name)},</p>
${paragraphs}
${card}
${button}
<p style="margin:8px 0 20px;">Thanks,<br>The team at ${esc(p.shop_name)}<br><span style="color:#5f6368;">Call us: ${esc(p.shop_phone)}</span></p>
</td></tr>
<tr><td style="padding:14px 28px;border-top:1px solid #e8eaed;color:#80868b;font-size:12px;line-height:1.5;">You're getting this because you're a customer of ${esc(p.shop_name)}. Reply STOP if you'd rather not get these reminders.</td></tr>
</table></td></tr></table></div>`;

return { json: { row_number: c.row_number, to_email: c.email, type: c.type, subject: c.subject, html, sheet: c.sheet } };

// Builds the owner's daily report after the loop finishes.
const p = $('Set Service Parameters').first().json;
const sent = $('Pick Today\'s Emails').all().map(i => i.json);
const rows = $('Read Customers Sheet').all().map(i => i.json);
const count = (t) => sent.filter(s => s.type === t).length;
const st = (r) => String(r.status || '').trim().toLowerCase();
const line = (r) => `  - ${r.customer_name} (${r.vehicle}) <${r.email}>${r.last_reply_text ? ' : "' + String(r.last_reply_text).slice(0, 120) + '"' : ''}`;
const section = (title, list) => [`${title} (${list.length})`, ...(list.length ? list.map(line) : ['  none']), ''];
const maxR = Number(p.max_reschedule_emails) || 2;
const body = [
  `Daily report for ${p.shop_name}, ${$now.toFormat('cccc d LLL yyyy')}`,
  `Mode: ${p.live_mode ? 'LIVE' : 'TEST (all emails went to you)'}`,
  '',
  `Emails processed today: ${sent.length}`,
  `  Service due (first / follow-up / final): ${count('due_1')} / ${count('due_2')} / ${count('due_3')}`,
  `  Appointment reminders: ${count('appointment')}`,
  `  Reschedule emails: ${count('reschedule')}`,
  '',
  ...section('Asked to book: confirm a time, then set appointment_date and status = booked', rows.filter(r => st(r) === 'booking_requested')),
  ...section('Waiting on your personal reply (see Gmail drafts)', rows.filter(r => st(r) === 'needs_owner_reply')),
  ...section('Missed appointment, no reply after all nudges: worth a phone call', rows.filter(r => st(r) === 'reschedule_requested' && Number(r.reschedule_count) >= maxR)),
].join('\n');
return [{ json: { subject: `${p.shop_name}: ${sent.length} customer emails today`, body } }];

// Matches each new Gmail reply to a customer (thread ID first, then email)
// and strips quoted history so Gemini only reads the new message.
const rows = $input.all().map(i => i.json);
const norm = (s) => String(s || '').trim().toLowerCase();
const out = [];
for (const m of $('Gmail Reply Trigger').all()) {
  const g = m.json;
  const fromEmail = norm(g.from?.value?.[0]?.address);
  const row = rows.find(r => g.threadId && String(r.thread_id || '').trim() === g.threadId)
           || rows.find(r => norm(r.email) === fromEmail);
  if (!row) continue; // not one of our customers

  const text = String(g.text || g.snippet || '')
    .split(/\r?\nOn [\s\S]{0,300}?wrote:/)[0]
    .split(/\r?\n-{2,}\s*Original Message/i)[0]
    .split(/\r?\n>/)[0]
    .trim()
    .slice(0, 1500);
  if (!text) continue;

  out.push({ json: {
    row_number: row.row_number,
    customer_name: String(row.customer_name || '').trim().split(' ')[0] || 'there',
    email: row.email,
    vehicle: row.vehicle || 'your vehicle',
    status: row.status || '',
    opt_out: norm(row.opt_out) === 'true' ? 'TRUE' : 'FALSE',
    appointment_date: row.appointment_date || '',
    reply_text: text,
    message_id: g.id,
    thread_id: g.threadId,
    subject: g.subject || 'Service reminder'
  }});
}
return out;

// Turns Gemini's one-word answer into the new sheet values.
// STOP is detected by keyword too, so opt-outs work even if Gemini is down.
// Anything unclear goes to the owner as a question.
const m = $('Match Replies to Customers').item.json;
const answer = String($input.item.json.text || '').toLowerCase();
let intent = ['book', 'question', 'stop', 'declined'].find((k) => new RegExp('\\b' + k + '\\b').test(answer)) || 'question';
if (/^\s*(stop|unsubscribe)\b/i.test(m.reply_text)) intent = 'stop';
const status = { book: 'booking_requested', question: 'needs_owner_reply', stop: 'opted_out', declined: 'declined' }[intent];
return { json: {
  ...m,
  intent,
  status,
  opt_out: intent === 'stop' ? 'TRUE' : m.opt_out,
  appointment_date: intent === 'book' ? '' : m.appointment_date,
} };

